package vn.covie.catalog.model;
import jakarta.persistence.*;
import java.sql.Types;
import java.time.Instant;
import java.util.Locale;
import java.util.UUID;
@Entity @Table(name="location_variants") public class LocationVariantEntity { @Id private UUID id; @Column(name="merchant_location_id",nullable=false) private UUID merchantLocationId; @Column(name="variant_id",nullable=false) private UUID variantId; @Column(nullable=false) private long price; @org.hibernate.annotations.JdbcTypeCode(Types.CHAR) @Column(name="currency_code",nullable=false,length=3) private String currencyCode; @Column(name="is_available",nullable=false) private boolean available; @Enumerated(EnumType.STRING) @Column(name="inventory_mode",length=20) private InventoryMode inventoryMode; @Column(name="preparation_time_minutes") private Integer preparationTimeMinutes; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; @Column(name="deleted_at") private Instant deletedAt; @Version @Column(nullable=false) private long version; protected LocationVariantEntity(){} public static LocationVariantEntity create(UUID id,UUID merchantLocationId,UUID variantId,long price,String currency,boolean available,InventoryMode inventoryMode,Integer preparationMinutes,Instant now){LocationVariantEntity offer=new LocationVariantEntity();offer.id=id;offer.merchantLocationId=merchantLocationId;offer.variantId=variantId;offer.changeOffer(price,currency,available,inventoryMode,preparationMinutes);offer.createdAt=now;offer.updatedAt=now;return offer;} public void changeOffer(long priceMinor,String currency,boolean available,InventoryMode inventoryMode,Integer preparationMinutes){if(priceMinor<0)throw new IllegalArgumentException("Price cannot be negative.");if(preparationMinutes!=null&&preparationMinutes<0)throw new IllegalArgumentException("Preparation time cannot be negative.");this.price=priceMinor;this.currencyCode=currency==null?null:currency.toUpperCase(Locale.ROOT);this.available=available;this.inventoryMode=inventoryMode;this.preparationTimeMinutes=preparationMinutes;} public void delete(Instant now){deletedAt=now;updatedAt=now;} public UUID getId(){return id;} public UUID getMerchantLocationId(){return merchantLocationId;} public UUID getVariantId(){return variantId;} public long getPrice(){return price;} public String getCurrencyCode(){return currencyCode;} public boolean isAvailable(){return available;} public InventoryMode getInventoryMode(){return inventoryMode;} public Integer getPreparationTimeMinutes(){return preparationTimeMinutes;} public Instant getDeletedAt(){return deletedAt;} public long getVersion(){return version;} }
